{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Practical psychotherapy in {{CITY}}, {{STATE}}</title>
  <link rel="stylesheet" href="assets/css/styles.css">
  <meta name="description" content="Short-term and ongoing psychotherapy for adults. Confidential, clinically grounded support to help you decide and act when life feels complicated.">
</head>
<body>
  <header class="site-header">
    <div class="wrap">
      <a class="logo" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav" aria-label="Main">
        <button id="navToggle" class="nav-toggle" aria-expanded="false">Menu</button>
        <ul id="navList" class="nav-list">
          <li><a href="/">Home</a></li>
          <li><a href="/about.html">Practice</a></li>
          <li><a href="/specialties.html">Specialties</a></li>
          <li><a href="/approach.html">How I Work</a></li>
          <li><a href="/fees.html">Investment</a></li>
          <li><a href="/faq.html">FAQs</a></li>
          <li><a href="/book.html">Schedule</a></li>
          <li><a href="/contact.html">Connect</a></li>
        </ul>
      </nav>
    </div>
  </header>

  <main>
    <section class="hero poster-hero">
      <svg class="pattern" viewBox="0 0 200 200" aria-hidden="true">
        <defs>
          <pattern id="p" width="20" height="20" patternUnits="userSpaceOnUse">
            <rect width="20" height="20" fill="#f7fbfc"></rect>
            <path d="M0 10 Q5 5 10 10 T20 10" stroke="#e6eef5" stroke-width="0.8" fill="none"></path>
          </pattern>
        </defs>
        <rect width="100%" height="100%" fill="url(#p)"></rect>
      </svg>
      <div class="wrap hero-inner">
        <div class="hero-copy">
          <h1 class="headline">Thoughtful therapy for the parts of life that feel noisy.</h1>
          <p class="subhead">Practical sessions for adults who want clearer thinking, steadier days, and kinder self-direction.</p>
          <div class="hero-actions">
            <a class="btn primary-cta" id="primaryCta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="/about.html">Meet the clinician</a>
          </div>
          <p class="meta">Sessions by appointment • Confidential practice in {{CITY}}, {{STATE}} • Telehealth and limited in-person availability</p>
        </div>
        <aside class="hero-side">
          <div class="card price-card">
            <h3>Pricing at a glance</h3>
            <div class="comparator">
              <div class="toggle">
                <button data-mode="monthly" class="mode-btn active">Monthly</button>
                <button data-mode="package" class="mode-btn">Package</button>
              </div>
              <div class="price-display">
                <div class="price-label">Individual session</div>
                <div class="price-number" id="priceNumber">$160</div>
                <div class="price-sub">or a package rate below</div>
              </div>
            </div>
            <a class="btn small" href="/fees.html">See full investment</a>
          </div>

          <div class="card mood-card">
            <h4>Check in: What describes you right now?</h4>
            <div class="mood-grid" role="tablist" aria-label="Mood selector">
              <button class="mood-btn" data-method="stabilize">Overwhelmed</button>
              <button class="mood-btn" data-method="clarify">Stuck or indecisive</button>
              <button class="mood-btn" data-method="focus">Need focus & planning</button>
              <button class="mood-btn" data-method="transition">Life transition</button>
            </div>
            <div class="method-recommendation" id="methodRec">
              <h5>Recommended approach</h5>
              <p class="method-title">Short-term stabilizing plan</p>
              <ul class="method-features">
                <li>Focused check-ins with coping skill refinement</li>
                <li>Tools to reduce immediate distress</li>
                <li>Clear next-step suggestions you can try between sessions</li>
              </ul>
              <a class="btn small" id="methodCta" href="{{PRIMARY_CTA_URL}}">Start with a single session</a>
            </div>
          </div>
        </aside>
      </div>
    </section>

    <section class="myth-truth wrap">
      <h2>Common beliefs, checked</h2>
      <div class="mt-grid">
        <div class="mt-card">
          <h3>Myth</h3>
          <p>Therapy is only for crisis or long-term problems.</p>
        </div>
        <div class="mt-card">
          <h3>Truth</h3>
          <p>Work can be brief or ongoing. We design a plan around your goals, not an arbitrary timeline.</p>
        </div>
        <div class="mt-card">
          <h3>Myth</h3>
          <p>Therapy always changes who you are.</p>
        </div>
        <div class="mt-card">
          <h3>Truth</h3>
          <p>Therapy offers clarity and choices; you remain in control of what you try and when.</p>
        </div>
      </div>
    </section>

    <section class="pillars wrap">
      <h2>How I work — four pragmatic pillars</h2>
      <div class="pillars-grid">
        <article>
          <h4>Listen & map</h4>
          <p>We begin by mapping what matters now: stressors, patterns, and strengths you already have.</p>
        </article>
        <article>
          <h4>Targeted tools</h4>
          <p>Practical strategies you can test between sessions: experiments, routines, and boundary-setting.</p>
        </article>
        <article>
          <h4>Plan with evidence</h4>
          <p>Short cycles of review to see what worked and what to change next — efficient and humane.</p>
        </article>
        <article>
          <h4>Confidential partnership</h4>
          <p>A steady, discreet space for reflection that respects your privacy and life demands.</p>
        </article>
      </div>
    </section>

    <section class="case-notes wrap">
      <h2>Illustrative notes (anonymized)</h2>
      <div class="notes">
        <article>
          <h5>Turning uncertainty into a short plan</h5>
          <p>Client felt stuck deciding about a job change. We clarified values, tested a 30-day experiment, and reviewed outcomes. Result: clearer decision framework and reduced anxiety about making the "perfect" choice.</p>
        </article>
        <article>
          <h5>Managing flare-ups</h5>
          <p>Frequent mood surges were interrupting sleep. We prioritized coping skills and sleep hygiene, used brief behavioral experiments, and developed a relapse-prevention checklist.</p>
        </article>
      </div>
    </section>

    <section class="faq wrap" id="faq">
      <h2>Questions people often ask</h2>
      <dl>
        <dt>What should I expect from the first session?</dt>
        <dd>A focused conversation about your goals and the brief plan we might test together. We also review confidentiality, boundaries, and scheduling.</dd>
        <dt>Is telehealth available?</dt>
        <dd>Yes. Telehealth is offered across {{STATE}} where permitted; in-person options are limited and by arrangement.</dd>
        <dt>How long are sessions?</dt>
        <dd>Standard sessions are 50 minutes. We also offer extended sessions when appropriate; see the Investment page for details.</dd>
      </dl>
    </section>

    <section class="cta wrap">
      <div class="cta-inner">
        <h2>Ready to explore a next step?</h2>
        <p>Schedule a brief consult to see whether this approach fits your needs. If it does, we draft a plan together and proceed at a pace you choose.</p>
        <div class="cta-actions">
          <a class="btn large primary-cta" id="finalCta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="/contact.html">Contact the practice</a>
        </div>
        <p class="small fineprint">Confidentiality note: Clinical records are maintained according to professional standards. This site does not provide crisis services; if you are in crisis, contact local emergency services or a crisis line.</p>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="wrap footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p>{{CITY}}, {{STATE}} • <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
      </div>
      <div>
        <p><a href="/privacy.html">Privacy & limits of confidentiality</a></p>
        <p><a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
    </div>
  </footer>

  <script src="assets/js/main.js" defer></script>
</body>
</html>"} 
