{"path":"assets/css/styles.css","content":"/* Base layout and poster-hero aesthetic */
:root{
  --bg:#ffffff; --muted:#556; --accent:#2b6ea3; --accent-2:#7fb0d8; --card:#f8fbfd; --soft:#eef6fb;
  --max-width:1100px; --radius:10px; --shadow:0 6px 18px rgba(20,30,40,0.08);
}
*{box-sizing:border-box}
html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial}
.wrap{max-width:var(--max-width);margin:0 auto;padding:1.25rem}
.site-header{background:linear-gradient(180deg, rgba(255,255,255,0.9), rgba(255,255,255,0.7));border-bottom:1px solid #eef3f6}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between}
.logo{font-weight:700;color:var(--accent);text-decoration:none}
.nav-list{list-style:none;margin:0;padding:0;display:flex;gap:0.5rem}
.nav-list a{color:var(--muted);text-decoration:none;padding:0.5rem}
.nav-toggle{display:none}

.poster-hero{position:relative;padding:2rem 0 3rem;background:linear-gradient(180deg,#fbfeff 0%,#f6fbfd 60%);overflow:hidden}
.poster-hero .pattern{position:absolute;right:-10%;top:-10%;width:60rem;height:60rem;opacity:0.35}
.hero-inner{display:grid;grid-template-columns:1fr 340px;gap:2rem;align-items:start}
.headline{font-size:clamp(1.5rem,3.2vw,2.4rem);margin:0 0 0.5rem;color:#0e2433}
.subhead{margin:0 0 1rem;color:#234;line-height:1.35}
.hero-actions{display:flex;gap:0.5rem;margin-bottom:0.75rem}
.btn{display:inline-block;padding:0.5rem 0.9rem;border-radius:8px;text-decoration:none;border:1px solid transparent;font-weight:600}
.primary-cta{background:var(--accent);color:#fff}
.btn.ghost{background:transparent;border-color:#dfeaf2;color:var(--muted)}
.meta{font-size:0.9rem;color:#6a7a86}
.hero-side .card{background:var(--card);padding:1rem;border-radius:10px;box-shadow:var(--shadow);margin-bottom:1rem}
.price-card h3{margin:0 0 0.5rem}
.comparator .toggle{display:flex;background:#fff;border-radius:8px;overflow:hidden;border:1px solid #e3eef6}
.mode-btn{flex:1;padding:0.45rem 0;border:0;background:transparent;cursor:pointer}
.mode-btn.active{background:linear-gradient(180deg,var(--accent-2),var(--accent));color:#fff}
.price-number{font-size:1.6rem;font-weight:700;color:var(--accent);margin:0.5rem 0}
.small{font-size:0.9rem}
.mood-card h4{margin-top:0}
.mood-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:0.5rem;margin:0.75rem 0}
.mood-btn{padding:0.6rem;border-radius:8px;border:1px solid #e6eef5;background:#fff;cursor:pointer}
.mood-btn.active{background:var(--accent);color:#fff;border-color:var(--accent)}
.method-recommendation{margin-top:0.75rem;background:linear-gradient(180deg,#fff,#f8fbfd);padding:0.75rem;border-radius:8px}
.method-title{font-weight:700;margin:0.25rem 0}
.method-features{margin:0.5rem 0 0;padding-left:1.2rem}

.myth-truth{padding:2rem 0}
.mt-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:1rem}
.mt-card{background:#fff;padding:1rem;border-radius:8px;border:1px solid #eef4f8}

.pillars{padding:2rem 0}
.pillars-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:1rem}
.pillars-grid article{background:var(--card);padding:1rem;border-radius:8px}

.case-notes{padding:2rem 0}
.notes{display:grid;grid-template-columns:1fr 1fr;gap:1rem}

.faq{padding:2rem 0}
.faq dl{margin:0}
.faq dt{font-weight:700}
.faq dd{margin:0 0 1rem 0;color:#344}

.cta{padding:2rem 0;background:linear-gradient(180deg,#fcfeff,#fbfdff)}
.cta-inner{display:flex;flex-direction:column;gap:0.5rem;align-items:flex-start}
.fineprint{color:#6d7b84;font-size:0.85rem}

.site-footer{border-top:1px solid #eef3f6;padding:1rem 0}
.footer-grid{display:flex;justify-content:space-between;align-items:center}

@media (max-width:900px){
  .hero-inner{grid-template-columns:1fr;}
  .pillars-grid{grid-template-columns:repeat(2,1fr)}
  .notes{grid-template-columns:1fr}
  .mt-grid{grid-template-columns:1fr}
  .nav-toggle{display:inline-block}
  .nav-list{position:absolute;right:1rem;top:3.5rem;background:#fff;border-radius:8px;padding:0.5rem;flex-direction:column;display:none}
  .nav-list.show{display:flex}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Nav toggle for small screens
  var navToggle = document.getElementById('navToggle');
  var navList = document.getElementById('navList');
  if(navToggle){
    navToggle.addEventListener('click', function(){
      var expanded = this.getAttribute('aria-expanded') === 'true';
      this.setAttribute('aria-expanded', !expanded);
      navList.classList.toggle('show');
    });
  }

  // Pricing comparator
  var priceNumber = document.getElementById('priceNumber');
  var modeButtons = document.querySelectorAll('.mode-btn');
  // Define prices (unique program naming)
  var prices = {
    monthly: 160,
    package: 1400 // package for 10 sessions
  };
  var animId = null;

  function animateNumber(el, start, end, duration){
    var startTime = null;
    if (animId) cancelAnimationFrame(animId);
    function tick(ts){
      if(!startTime) startTime = ts;
      var t = Math.min((ts - startTime)/duration, 1);
      var val = Math.round(start + (end - start) * (1 - Math.pow(1 - t, 2))); // ease-out
      el.textContent = '$' + val + (end === prices.package ? ' package' : '');
      if(t < 1){
        animId = requestAnimationFrame(tick);
      }
    }
    animId = requestAnimationFrame(tick);
  }

  modeButtons.forEach(function(btn){
    btn.addEventListener('click', function(){
      modeButtons.forEach(function(b){b.classList.remove('active')});
      this.classList.add('active');
      var mode = this.getAttribute('data-mode');
      var current = parseInt(priceNumber.textContent.replace(/[^0-9]/g,'')) || prices.monthly;
      animateNumber(priceNumber, current, prices[mode], 700);
    });
  });

  // Set initial label format
  priceNumber.textContent = '$' + prices.monthly;

  // Mood-to-Method selector
  var moodButtons = document.querySelectorAll('.mood-btn');
  var methodRec = document.getElementById('methodRec');
  var methodTitle = methodRec.querySelector('.method-title');
  var methodList = methodRec.querySelector('.method-features');
  var methodCta = document.getElementById('methodCta');

  var methods = {
    stabilize:{
      title:'Stabilizing plan',
      features:['Short, practical skills to reduce urgent distress','Weekly check-ins to adjust strategies','Clear steps to support daily functioning'],
      cta:'Book a stabilizing session',
      url:'{{PRIMARY_CTA_URL}}'
    },
    clarify:{
      title:'Clarity-focused work',
      features:['Explore values and priorities','Small experiments to test choices','Decision support and accountability'],
      cta:'Schedule a clarity consult',
      url:'{{PRIMARY_CTA_URL}}'
    },
    focus:{
      title:'Task-focused coaching',
      features:['Goal mapping and time-bound plans','Practical strategies to reduce friction','Weekly review to keep momentum'],
      cta:'Start a planning session',
      url:'{{PRIMARY_CTA_URL}}'
    },
    transition:{
      title:'Transition navigation',
      features:['Process the change compassionately','Identify practical next steps','Support integrating new roles and routines'],
      cta:'Explore transition support',
      url:'{{PRIMARY_CTA_URL}}'
    }
  };

  moodButtons.forEach(function(btn){
    btn.addEventListener('click', function(e){
      moodButtons.forEach(function(b){b.classList.remove('active')});
      this.classList.add('active');
      var key = this.getAttribute('data-method');
      var m = methods[key];
      // animate text change: simple fade
      methodRec.style.opacity = 0.25;
      setTimeout(function(){
        methodTitle.textContent = m.title;
        // rebuild list
        methodList.innerHTML = '';
        m.features.forEach(function(f){
          var li = document.createElement('li'); li.textContent = f; methodList.appendChild(li);
        });
        methodCta.textContent = m.cta;
        methodCta.setAttribute('href', m.url);
        methodRec.style.opacity = 1;
      },220);
    });
  });

  // Accessibility: allow keyboard activation for mood buttons
  document.querySelectorAll('.mood-btn, .mode-btn').forEach(function(el){
    el.addEventListener('keyup', function(e){ if(e.key === 'Enter' || e.key === ' ') el.click(); });
  });

})();
"} 
